class Solution:

	def countWays(self, n, k):
		dp = []
		for i in range(n):
			dp.append([0, 0])
		dp[0] = [k, 0]
		for i in range(1, n):
			dp[i][0] = (dp[i - 1][0] * (k - 1) + dp[i - 1][1] * (k - 1)) % (10 ** 9 + 7)
			dp[i][1] = dp[i - 1][0]
		return sum(dp[n - 1]) % (10 ** 9 + 7)
